const periods = [1,2,3,4,5,6];
const days = ["星期一","星期二","星期三","星期四","星期五"];

function getAllClasses() { return Object.keys(scheduleData).sort(); }

function getAllTeachers() {
  var s = new Set();
  for (var cls in scheduleData) {
    for (var d in scheduleData[cls]) {
      for (var p in scheduleData[cls][d]) {
        var t = scheduleData[cls][d][p].teacher;
        if (t) s.add(t);
      }
    }
  }
  return Array.from(s).sort(function(a,b){return a.localeCompare(b,'zh-CN');});
}

function getTeacherSchedule(name) {
  var ts = {}; var total = 0;
  for (var cls in scheduleData) {
    for (var i=0;i<days.length;i++) {
      var d = days[i]; if (!ts[d]) ts[d] = {};
      for (var j=0;j<periods.length;j++) {
        var p = periods[j]; var l = scheduleData[cls][d] && scheduleData[cls][d][p] ? scheduleData[cls][d][p] : null;
        if (l && l.teacher === name) { ts[d][p] = {course:l.course,teacher:l.teacher,room:l.room,class:cls}; total++; }
      }
    }
  }
  return {schedule:ts, total:total};
}
